import{_ as o,o as a,c as r,a4 as t}from"./chunks/framework.kn7HWrZO.js";const p=JSON.parse('{"title":"术语表","description":"","frontmatter":{"editSource":"docs/glossary.zh.md","rawMarkdownPath":"reference/glossary.md"},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md"}'),n={name:"reference/glossary.md"};function s(l,e,c,d,i,g){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>DeepSeek Harness 的领域词汇为每个概念规定一个规范术语。各术语通过标准 Markdown 锚点链接到相应条目；实现细节留在各包的 README 与 Agent Note 中。</p><h2 id="capability-seam" tabindex="-1">capability-seam <a class="header-anchor" href="#capability-seam" aria-label="Permalink to &quot;capability-seam&quot;">​</a></h2><ul><li><strong>seam</strong>：一种包含三种角色的<em>可替换能力</em>：<strong>Service Definition</strong>（拥有自身 <code>ctx.&lt;key&gt;</code> 和词汇类型的 Cordis <code>Service</code>——可以是 <code>ShellExecutor</code> 这样的抽象类，也可以是 <code>WebRuntime</code> 这样的具体注册表，绝不是 TypeScript <code>interface</code>）、一个或多个 <strong>Service Provider</strong>，以及一个或多个注入该服务的 <strong>Consumer</strong>。<code>packages/shell</code> 是规范范例：<code>dsh-shell</code>（Service Definition）、<code>dsh-bash-local</code> / <code>dsh-bash-sandbox</code>（提供方），以及 <code>dsh-tool-bash</code>（Consumer）。角色需要独立演进时通常位于不同包，但属于同一关注点时，一个包也可以承担多个角色（<code>dsh-user-approval</code> 在同一个包中承担 approval seam 的 Service Definition 与其具体实现）。seam 是完整能力，绝不是其中一个角色；该术语仅保留此义，能力成员应按其角色、类、服务、约定或扩展点命名。</li></ul><h2 id="agent-scope" tabindex="-1">agent-scope <a class="header-anchor" href="#agent-scope" aria-label="Permalink to &quot;agent-scope&quot;">​</a></h2><ul><li><strong>scope</strong>：按 agent（智能体）划分的注册单位。一项贡献（工具、提示词段、变量、限制、监听器）要么是<em>全局的</em>（对所有 agent 可见），要么是<em>带作用域的</em>（归属于恰好一个 <a href="#scope-key">scope key</a>）。只有两层，采用扁平结构：带作用域的注册不会向下继承给 subagent；子树行为通过 <a href="#lineage">lineage</a> 数据表达，从不通过 scope 结构。</li><li><strong>scope key</strong>：scope 的不透明标识，按对象同一性比较。harness 约定：一个活跃的 agent 就是其自身 scope 的 key。<a id="scope-key"></a></li><li><strong>agent 上下文（<code>agent.ctx</code>）</strong>：agent 的带作用域上下文；通过它进行的注册既具有 scope 可见性，其生命周期也绑定到该 scope（同一事实决定两者），其上的监听器参与该 agent 的 scope 过滤分发。注册表主体事件可以根据各自的事件约定有意保持不过滤。</li><li><strong>scope carrier</strong>：scope 过滤分发所携带的 <code>thisArg</code>（由 <code>scopeTarget</code> 构建）；其过滤器放行无标签监听器加上主体自身的监听器。<em>无主体</em>的 carrier（没有 key）只放行无标签监听器。</li><li><strong>scoped dispatch</strong>：规则是：关于某个 agent 的活动的事件以该 agent 的 carrier 进行分发。关于注册表本身的事件（如「一个工具被添加了」）属于<em>注册表主体</em>事件，保持不过滤。</li><li><strong>shadowing</strong>：最具体者胜出的名称解析：一个带作用域的工具／片段／变量仅在该 scope 内替换同名的全局对应项。这是按 agent 定制 persona 和按 agent 定制工具变体的机制。</li><li><strong>restriction / scope-local 注册</strong>：restriction（<code>tools.restrict</code>）为单个 scope 过滤全局工具集合（多个 restriction 取交集组合）；scope-local 注册在过滤之后合并。被过滤掉的全局工具既不出现在提示词中，也拒绝执行，与不存在的工具无法区分。</li><li><strong>setup window</strong>：创建者组装 agent 作用域环境的创建时隙（<code>CreateAgentOptions.setup</code>）：此时 scope 和 agent 对象已存在，但 agent 或会话尚未发布，<code>agent/created</code> 尚未触发，首次提示词尚未组装。setup 只做注册，从不驱动 agent。</li><li><strong>lineage</strong>：以数据形式携带的父子关系事实（<code>parentSession</code>、持久的 <code>delegationDepth</code>、运行时 <code>subagentDepth</code>）；从不影响可见性。<a id="lineage"></a></li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><ul><li><strong>目标</strong>：附着在现有会话上的单个持久完成目标，带有按修订号演进的 <code>active</code> / <code>paused</code> / <code>blocked</code> / <code>complete</code> 阶段和 Goal Round 上限；<code>blocked</code> 保留策略代码与说明。目标是一种状态，不是调度器，也不是一段独立对话；会话日志仍是其真源。</li><li><strong>Goal Round</strong>：为当前目标接纳的一次续行周期。同会话驱动器将 Goal Round 具体化为一个由目标触发的<a href="#turn">轮次</a>，其中可包含零个或多个步骤；同一会话中无关的人类轮次不消耗 Goal Round 上限。<a id="goal-round"></a></li><li><strong>目标激活</strong>：续行消费方接纳下一个 Goal Round 的进程本地权限。激活态为 <code>armed</code> 或 <code>disarmed</code>；它有意不参与持久回放，因此在恢复或 fork 后，只有随后通过 <code>/goal</code> 或模型工具执行一次经人类授权的恢复变更，自动工作才能开始。</li></ul><h2 id="人类命令" tabindex="-1">人类命令 <a class="header-anchor" href="#人类命令" aria-label="Permalink to &quot;人类命令&quot;">​</a></h2><ul><li><strong>人类命令</strong>：以斜杠开头的指令，由面向人类的适配器通过 <code>ctx.commands</code> 解释并执行，不会成为模型消息。它既不同于面向模型的工具，也不同于通过 <code>ctx.shell</code> 执行 shell 命令。</li><li><strong>命令平面</strong>：由 UI 适配器和命令插件负责的发现、解析、分发、取消与结果渲染机制。除非处理器另行改变持久领域，否则命令输出属于 UI 状态。</li><li><strong>目标命令</strong>：<code>/goal</code> 是由 <code>dsh-command-goal</code> 提供的人类命令；它直接观察或更改当前目标，而目标领域拥有每条持久且模型可见的记录。</li></ul><h2 id="循环层级" tabindex="-1">循环层级 <a class="header-anchor" href="#循环层级" aria-label="Permalink to &quot;循环层级&quot;">​</a></h2><ul><li><strong>轮次</strong>：会话中一次对已接纳输入的排空过程，在模型及其工具停止工作或终止策略介入后结束。<a id="turn"></a></li><li><strong>步骤</strong>：一次模型请求，以及由模型响应引发的工具执行；一个轮次包含零个或多个步骤。<a id="step"></a></li><li><strong>Round</strong>：承载一个轮次的外层策略迭代，例如一个 <a href="#goal-round">Goal Round</a> 或一次使用全新 agent 的 Ralph 尝试。Round 计数器归该策略所有，并不统计会话中的每个轮次。<a id="round"></a></li><li><strong>交互段</strong>：连续的<a href="#turn">轮次</a>，从首个<a href="#step">步骤</a>接纳真人输入的轮次起，到下一个这样的轮次为止；由通知（子 agent 完成、Goal Round、定时任务等）唤醒的轮次归入前面的交互段。Chat 的「下次发送时收起」保持最新交互段展开。<a id="exchange"></a></li></ul><h2 id="ralph" tabindex="-1">Ralph <a class="header-anchor" href="#ralph" aria-label="Permalink to &quot;Ralph&quot;">​</a></h2><ul><li><strong>Ralph 循环</strong>：一次面向不可变目标的前台全新 agent 工作流运行。它是由工作流和 subagent 原语组合而成的面向模型的工具策略，不是同会话目标、agent loop（智能体循环）模式、调度器或通用工作流脚本功能。<a id="ralph-loop"></a></li><li><strong>Ralph Round</strong>：<a href="#ralph-loop">Ralph 循环</a>中的一个全新子会话。子会话不接收父会话或此前子会话的对话种子；共享工作区和一份有界的 <a href="#ralph-handoff">Ralph 交接</a>承载跨 Round 的状态。<a id="ralph-round"></a></li><li><strong>Ralph 交接</strong>：从一个仍需继续的 Ralph Round 传给下一个 Ralph Round 的规范化、有界结构化报告，包含状态、摘要、证据、后续步骤和阻塞说明。它补充共享工作区，而不取代工作区的权威地位。<a id="ralph-handoff"></a></li></ul>',14)])])}const u=o(n,[["render",s]]);export{p as __pageData,u as default};
